<?php require_once __DIR__.'/includes/database.php';require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/images.php';$pageTitle=t('Events','ዝግጅቶች');$events=[];try{$events=db()->query("SELECT * FROM events WHERE status='published' ORDER BY event_date ASC,start_time ASC")->fetchAll();}catch(Throwable $e){}require __DIR__.'/includes/header.php';?>
<section class="page-hero page-hero-image" style="<?=e(hero_style('events'))?>"><div class="container"><span class="eyebrow"><?=e(t('Home / Events','መነሻ / ዝግጅቶች'))?></span><h1><?=e(t('Upcoming Events','የሚመጡ ዝግጅቶች'))?></h1><p><?=e(t('Friday worship, Bible study, prayer meetings, conferences and special programs.','የዓርብ አምልኮ፣ የመጽሐፍ ቅዱስ ጥናት፣ የጸሎት ስብሰባ፣ ኮንፈረንስ እና ልዩ ፕሮግራሞች።'))?></p></div></section>
<section class="section"><div class="container"><div class="event-grid"><?php if(!$events):?><div class="card"><h3><?=e(t('No upcoming events yet','እስካሁን የሚመጣ ዝግጅት የለም'))?></h3><p><?=e(t('Please check again soon.','በቅርቡ እንደገና ይጎብኙ።'))?></p></div><?php else:foreach($events as $r):$ts=strtotime($r['event_date']);?><article class="event-card-large"><div class="event-date-box"><b><?=e(strtoupper(date('M',$ts)))?></b><strong><?=e(date('d',$ts))?></strong></div><div><h3><?=e(text_lang($r,'title'))?></h3><small>📅 <?=e(date('M d, Y',$ts))?><?php if($r['start_time']):?> · <?=e(date('g:i A',strtotime($r['start_time'])))?><?php endif;?><?php if($r['end_time']):?> – <?=e(date('g:i A',strtotime($r['end_time'])))?><?php endif;?></small><p>📍 <?=e($r['location']?:'Durame Campus')?></p><?php if(text_lang($r,'description')):?><p><?=e(text_lang($r,'description'))?></p><?php endif;?><?php if(!empty($r['registration_enabled'])):?><a class="btn primary small" href="<?=e(service_url())?>" target="_blank" rel="noopener"><?=e(t('Register','ይመዝገቡ'))?> ↗</a><?php endif;?></div></article><?php endforeach;endif;?></div></div></section><?php require __DIR__.'/includes/footer.php';?>
